// Types for the JSON content in `src/data/`. Generated by scripts/reference/build-data.mjs.

export interface MediaRef {
	src: string;
	alt: string;
	width?: number;
	height?: number;
}

export interface Term {
	slug: string;
	label: string;
}

export interface PortableTextSpan {
	_type: "span";
	text: string;
}

export interface ImageMetadata {
	width: number;
	height: number;
}

export interface PortableTextBlock {
	_type: "block";
	style: "normal" | "h1" | "h2" | "h3" | "h4" | "blockquote";
	children: PortableTextSpan[];
}

export type PortableText = PortableTextBlock[];

export interface BaseEntry {
	id: string;
	slug: string;
	status: string;
	order?: number;
	publishedAt?: string;
	terms?: Record<string, Term[]>;
}

export interface Service extends BaseEntry {
	title: string;
	featured_image: MediaRef | null;
	price_label: string | null;
	audience_label: string | null;
	format: string | null;
	notice: string | null;
	booking_url: string | null;
	content: PortableText;
}

export interface ResourceCta {
	label: string;
	url: string;
}

export interface Resource extends BaseEntry {
	title: string;
	featured_image: MediaRef | null;
	badge_label: string | null;
	ctas: ResourceCta[];
	video_url: string | null;
	excerpt: string | null;
	content: PortableText;
}

export interface Testimonial extends BaseEntry {
	title: string | null;
	quote: string | null;
	author: string | null;
}

export interface Post extends BaseEntry {
	title: string;
	excerpt: string | null;
	featured_image: MediaRef | null;
	content: PortableText;
}

export interface MenuItem {
	type: string;
	label: string;
	url: string;
	children?: MenuItem[];
}

export interface Menu {
	name: string;
	label: string;
	items: MenuItem[];
}

export interface Banner {
	layout: "portrait" | "overlay";
	title: string;
	subtitle: string;
	buttonLabel: string;
	buttonUrl: string;
	image: string;
	mobileImage?: string;
}

export interface SiteSettings {
	title: string;
	tagline: string;
	url: string;
	logo: MediaRef | null;
	social: Record<string, string>;
	notice?: string;
}

export interface Taxonomy {
	name: string;
	label: string;
	labelSingular: string;
	terms: Term[];
}
